def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_d = sum(1 for a in my if a == 'D')
    opp_d = sum(1 for a in op if a == 'D')
    my_c = n - my_d

    # Initial cooperative phase followed by three probing defections.
    if n < 5:
        return 'C'
    if n == 5:
        return 'D'
    if n == 6:
        return 'D'
    if n == 7:
        return 'D'

    # If the opponent never defected despite our three probes, they are a sucker.
    if opp_d == 0:
        return 'D'

    last_my = my[-1]
    last_opp = op[-1]

    # Forgive isolated defections; punish only frequent defectors.
    if last_opp == 'D':
        if opp_d / n > 0.4:
            return 'D'
        return 'C'

    # Opponent cooperated last round.
    if last_opp == 'C':
        if last_my == 'D':
            return 'C'
        else:
            # Periodic defection every 9 rounds to exploit forgiving opponents
            # while keeping exploiters in check.
            if n > 10 and n % 9 == 0:
                return 'D'
            # Prevent our cooperation rate from reaching the exploitable threshold.
            if n > 10 and my_c * 10 >= n * 9:
                return 'D'
            return 'C'

    return 'C'
